/** Neutral fallback so a missing key never renders a broken image. */
const FALLBACK = IMAGES["editorial/map"] ?? "";

/** Resolve an image key to a URL. */
export function img(key: string): string {
  return IMAGES[key] ?? FALLBACK;
}
